// Machine Design Guides — shared drawing notes library, source of truth for the Drawing Notes Library page
// (calculators/drawing-notes/drawing-notes-library.html). Plain JS (not .json), loaded via
// <script src="../../data/drawing-notes.js"> — same reasoning as data/manifest.js (works under file://).
//
// Assigns window.MDG_DRAWING_NOTES = { updated, extra, sections }.
//   sections[]  id, num, title, notes[]. One section per process group; the page sorts notes A to Z by topic.
//   notes[]     id, topic, text, c (comment), m (applicable materials), cost (1-5), types[].
//               A note with no types carries its own `text`. A note with types has `text: null`; each type carries
//               its own name, text, c, m, cost (c, m, cost fall back to the note's when null).
//   m[]         { t: material type slug from data/materials.js, label, g?: [grade name fragments] } or
//               { t: null, label: "All metals", metals: true }. An empty/absent m means any material.
//   extra[]     material classes the page offers that are not in data/materials.js yet (slug, title).
//   text        One sentence per line (\n). [] = value the engineer must supply, [A | B] = pick one,
//               [COMPANY] = company name. Wording follows BS 8888.
//   cost        Approximate relative process cost per part for a small lot: 1 lowest to 5 highest. Estimates, not live.
// Comments, applicable materials and cost bands are drafted guidance and have not been checked against the cited standards.
// To add a note or type, edit this file; the page picks it up.
window.MDG_DRAWING_NOTES = {
  "updated": "2026-11-23",
  "extra": [{"slug": "composites", "title": "Composites"}, {"slug": "electrical-steel", "title": "Electrical steel"}, {"slug": "magnets", "title": "Magnets"}],
  "sections": [
    {"id": "s1", "num": 1, "title": "General and certification", "notes": [
      {"id": "n1_1", "topic": "3D model use", "text": "MACHINE TO 3D CAD U.O.S. PROFILE 0.4 A B C", "c": "Makes the 3D model the definition of undimensioned surfaces, within the profile tolerance to datums A B C. Splines and threads still need tabulated data.", "m": [], "cost": 1, "types": []},
      {"id": "n1_2", "topic": "Certificates", "text": null, "c": "Call up the heat treatment certificate for any hardened, aged or tempered part so the condition is traceable.", "m": [{"t": null, "label": "All metals", "metals": true}], "cost": 1, "types": [{"name": "Material", "text": "MATERIAL CERTIFICATE OF CONFORMITY REQUIRED.", "c": null, "m": null, "cost": null}, {"name": "Material and heat treatment", "text": "MATERIAL AND HEAT TREATMENT CERTIFICATE OF CONFORMITY REQUIRED.", "c": null, "m": null, "cost": null}]},
      {"id": "n1_3", "topic": "Machining condition", "text": "MACHINE ALL OVER WITH MATERIAL IN ANNEALED CONDITION.\nDIMENSIONS APPLY AFTER HEAT TREATMENT.", "c": "Machine soft, then heat treat. Allow stock for distortion where tolerances are tight.", "m": [{"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}, {"t": "stainless-steel", "label": "Stainless steels"}, {"t": "tool-steel", "label": "Tool steels"}], "cost": 1, "types": []},
      {"id": "n1_4", "topic": "Material condition for turning", "text": "ROUGH TURN ALL OVER WITH MATERIAL IN CONDITION A.\nFINISH INTERNAL GEOMETRY BETWEEN POINTS [] SHOWN IN SECTION [].", "c": "Two-stage turn: rough in the stated condition, then finish the marked geometry. Define the condition and the points per part.", "m": [{"t": null, "label": "All metals", "metals": true}], "cost": 1, "types": []},
      {"id": "n1_5", "topic": "Special characteristics", "text": "SPECIAL CHARACTERISTICS ARE IDENTIFIED AS: ▽ CRITICAL  ◯ SIGNIFICANT", "c": "Triangle = critical, oval = significant. Use sparingly: each one adds inspection effort.", "m": [], "cost": 1, "types": []}
    ]},
    {"id": "s2", "num": 2, "title": "Surface treatments and coatings", "notes": [
      {"id": "n2_1", "topic": "Anodise (aluminium)", "text": null, "c": "Clear or black for corrosion and appearance. Hard anodise for wear and thickness. Add PTFE for low friction.", "m": [{"t": "aluminum", "label": "Aluminium alloys"}], "cost": 3, "types": [{"name": "Clear anodise", "text": "ANODISE CLEAR TO ISO 7599 AA[15 | 20 | 25].\nALL DIMENSIONS APPLY TO THE FINISHED PART AFTER ANODISING.\nRa 0.2-0.8 µm", "c": "Thin film (typically 5 to 25 µm) for corrosion protection and appearance. State that dimensions apply after anodising. AA number = thickness class (µm): AA15 mild outdoor, AA20 outdoor, AA25 severe or marine.", "m": null, "cost": 2}, {"name": "Matt black anodise", "text": "ANODISE MATT BLACK TO ISO 7599 AA[15 | 20 | 25].\nALL DIMENSIONS APPLY TO THE FINISHED PART AFTER ANODISING.\nRa 0.2-0.8 µm", "c": "Dyed film, appearance first. Dye can fade in UV and colour varies by alloy and batch. AA number = thickness class (µm): AA15 mild outdoor, AA20 outdoor, AA25 severe or marine.", "m": null, "cost": 2}, {"name": "Hard anodise", "text": "HARD ANODISE TO ISO 10074.\nTHICKNESS [36-44 µm TOTAL (50% GROWTH INTO SURFACE, 50% OUT OF SURFACE) | 50 µm MIN | 50-60 µm].\n[DYE BLACK.]\nSEAL: [COLD CHEMICAL SEAL (NICKEL FLUORIDE BASED) | DUPLEX SEAL | DO NOT SEAL].\nMASK THREADS.\nALL DIMENSIONS APPLY AFTER ANODISING.", "c": "Thick, dense film for wear and corrosion resistance. US equivalent: MIL-PRF-8625 Type III. About half the thickness grows out of the surface. Thickness: 36-44 µm general wear; 50 µm MIN or 50-60 µm for heavy wear or higher dielectric strength. Break sharp edges. High-copper wrought and high-silicon cast alloys anodise poorly. Seals: cold chemical (nickel fluoride based) plugs the pores at low temperature; duplex is a two-stage seal, typically cold then hot water or metal salt, for best corrosion resistance; do not seal leaves open pores for lubricant, PTFE or bonding and is least corrosion resistant.", "m": null, "cost": 3}, {"name": "Hard anodise + PTFE", "text": "HARD ANODISE TO ISO 10074.\nTHICKNESS [36-44 µm TOTAL (50% GROWTH INTO SURFACE, 50% OUT OF SURFACE) | 50 µm MIN | 50-60 µm].\n[DYE BLACK.]\nDO NOT SEAL.\nMASK THREADS.\nPTFE COATING TO AMS 2482 TYPE [1 | 2].\nALL DIMENSIONS APPLY AFTER COATING.", "c": "As hard anodise but unsealed, with PTFE for low friction. Thickness options as hard anodise. AMS 2482 Type 1 = PTFE impregnated; Type 2 = PTFE codeposited (Type 1 if not stated). Alloys under 5% Cu and 8% Si. Dimensions apply after coating.", "m": null, "cost": 4}]},
      {"id": "n2_2", "topic": "Blast, tumble and clean", "text": null, "c": "Tumble for bulk deburring, vapour blast for cleaning or an even matt look.", "m": [{"t": null, "label": "All metals", "metals": true}], "cost": 1, "types": [{"name": "Tumble", "text": "TUMBLE AFTER MACHINING TO Ra 1.6 µm", "c": "Deburrs and evens the surface in bulk. Low cost, but edges round and small features can be damaged.", "m": null, "cost": 1}, {"name": "Vapour blast, clean", "text": "VAPOUR BLAST PART TO CLEAN.", "c": "Light wet blast that cleans without removing material and leaves a uniform matt finish.", "m": null, "cost": 2}, {"name": "Vapour blast, cosmetic", "text": "COSMETIC VAPOUR BLAST ALL OVER, EVEN FINISH REQUIRED [OUTSIDE ONLY, SEE REFERENCE VIEW].", "c": "Hides tool marks. State which faces are cosmetic.", "m": null, "cost": 2}]},
      {"id": "n2_3", "topic": "Busbar insulation coat", "text": "INSULATION POWDER COAT AKZONOBEL RESICOAT EL201 HFG03R RAL 2003, THICKNESS 0.4-0.6 mm PER SIDE, THERMAL INDEX 130 °C.\nBREAK SHARP EDGES WITH A DEBURRING TOOL, MINIMUM RADIUS 0.5 mm.\nBUSBARS TO BE TESTED TO 3 kV MIN.", "c": "Powder-coat insulation for busbars. Break sharp edges first so the coat does not thin at corners.", "m": [{"t": "aluminum", "label": "Aluminium alloys"}, {"t": "copper-alloy", "label": "Copper alloys"}], "cost": 3, "types": []},
      {"id": "n2_4", "topic": "Chemical conversion coating", "text": null, "c": "Choose by substrate: Surtec 650 for aluminium, passivation for stainless, phosphate or black oxide for steel.", "m": [], "cost": 2, "types": [{"name": "Black oxide", "text": "APPLY BLACK OXIDE COATING TO MIL-DTL-13924, CLASS [1 | 4].\nALL DIMENSIONS APPLY AFTER COATING.", "c": "Cosmetic with minimal dimensional change. Little corrosion resistance unless oiled. Class 1: carbon and low-alloy steel. Class 4: 300-series stainless.", "m": [{"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}, {"t": "stainless-steel", "label": "Stainless steels"}, {"t": "tool-steel", "label": "Tool steels"}], "cost": 1}, {"name": "Passivation", "text": "PASSIVATE THE COMPLETE PART AFTER ALL MACHINING OPERATIONS TO AMS 2700 METHOD 1 TYPE 2 OR 8.", "c": "Removes free iron and restores the passive film, with no dimension change. Type 8 preferred: no dichromate and no performance benefit from Type 2 found. Type 2 is nitric with sodium dichromate. Check the substrate grade: Type 2 has flash-attacked 416.", "m": [{"t": "stainless-steel", "label": "Stainless steels"}], "cost": 1}, {"name": "Phosphate", "text": "APPLY PHOSPHATE COATING ALL OVER TO MIL-DTL-16232 METHOD Z CLASS 4 (5-15 µm THICKNESS REF), EXCEPT AS NOTED BELOW: ABRASIVE BLAST PART WITH 600 GRIT ALUMINIUM OXIDE AT 3 bar MAX.\nUSE A CALCIUM-MODIFIED ZINC PHOSPHATE BATH WITH CALCIUM HELD AT SATURATION TO ACHIEVE THE DRAWING SURFACE ROUGHNESS AFTER PHOSPHATE FINISH IS APPLIED.\nNO MINIMUM WEIGHT OF PHOSPHATE COATING IS REQUIRED.\nVISUALLY INSPECT COATING FOR UNIFORM COVERAGE.", "c": "Zinc phosphate base for paint or oil that also holds lubricant. Check thread fit after coating.", "m": [{"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}, {"t": "tool-steel", "label": "Tool steels"}], "cost": 2}, {"name": "Surtec 650", "text": "COAT WITH SURTEC 650 TO MIL-DTL-5541 TYPE [II | I] CLASS [1A | 3], LAYER WEIGHT >110 mg/m².\nALL DIMENSIONS APPLY AFTER COATING.", "c": "Trivalent chromium conversion coat for aluminium to MIL-DTL-5541. Type I contains hexavalent chromium; Type II (none) preferred on H&S grounds. Class 1A = optimum corrosion resistance. Class 3 = corrosion protection with low electrical resistance.", "m": [{"t": "aluminum", "label": "Aluminium alloys"}], "cost": 2}]},
      {"id": "n2_5", "topic": "Metallic plating", "text": null, "c": "Zinc for general steel, nickel or tin for electrical contact faces, electroless nickel for wear and uniform build.", "m": [], "cost": 2, "types": [{"name": "Electroless nickel", "text": "ELECTROLESS NICKEL PLATING TO ISO 4527, THICKNESS 25-30 µm (SC3).\nSURFACE HARDNESS AS PLATED (TARGET 48-52 HRC).", "c": "Even thickness in holes and recesses. Hard and wear resistant, and hardness rises with post-plate heat treatment.", "m": [{"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}, {"t": "aluminum", "label": "Aluminium alloys"}, {"t": "copper-alloy", "label": "Copper alloys"}], "cost": 3}, {"name": "Electroplated nickel", "text": "ELECTROPLATED NICKEL TO BS EN ISO 1456:2009 [Al | Cu]/Ni5 SC[].\nNICKEL THICKNESS 5 µm MIN.\nALL SURFACES TO BE DEGREASED, ETCHED AND ZINCATED, CLEANED AND FREE OF OXIDES PRIOR TO PLATING.\nALL EDGES, HOLES AND CONTACT SURFACES MUST BE FULLY PLATED.", "c": "Contact finish for busbars. Thickness is uneven on edges and in recesses, so specify full coverage of contact faces. Al or Cu = substrate; zincate step is for aluminium only. SC = service condition number (higher = more severe).", "m": [{"t": "aluminum", "label": "Aluminium alloys"}, {"t": "copper-alloy", "label": "Copper alloys"}], "cost": 2}, {"name": "Tin plate", "text": "BRIGHT ELECTRO TIN PLATING TO BS 1872", "c": "Low contact resistance and solderable on copper. Bright tin can grow whiskers.", "m": [{"t": "copper-alloy", "label": "Copper alloys"}], "cost": 2}, {"name": "Zinc plate", "text": "ZINC PLATE TO ISO 19598: Fe//Zn[8 | 12 | 25]//[An | Cn]//[T0 | T2].\nMASK SURFACES AS SHOWN.\nALL DIMENSIONS APPLY AFTER PLATING.", "c": "Sacrificial corrosion protection for steel. Zn number = minimum thickness (µm): 8 indoor, 12 outdoor, 25 severe outdoor. An clear, Cn iridescent (Cr(VI)-free); T0 no sealer, T2 sealer. High-strength steel (above about 1000 MPa) needs embrittlement relief baking.", "m": [{"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}], "cost": 1}]},
      {"id": "n2_6", "topic": "Nameplate (Metalphoto)", "text": "NAMEPLATE TO BE METALPHOTO (PHOTOSENSITIVE ANODISED ALUMINIUM) OF 0.0762 mm STOCK THICKNESS.", "c": "Photosensitive anodised aluminium: the image is sealed in the anodic layer, so it is durable for permanent ID plates.", "m": [{"t": "aluminum", "label": "Aluminium alloys"}], "cost": 3, "types": []},
      {"id": "n2_7", "topic": "Paint and powder coat", "text": null, "c": "For steel tooling and fixtures. Zinc spray or zinc-rich systems give the longest corrosion life.", "m": [{"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}], "cost": 2, "types": [{"name": "Blast, prime and powder coat", "text": "BLAST CLEAN TO ISO 8501 Sa 2.5.\n[ETCH PRIME 10-20 µm | ZINC-RICH PRIMER 75-100 µm | EPOXY PRIMER].\nPOWDER COAT [RAL xxxx | BLACK], 80 µm DRY.\nTHREADS TO BE PRIMED BUT FREE FROM POWDER COAT.", "c": "Standard finish for steel tooling. Keep threads free of powder coat. Primer: etch for adhesion (indoor), zinc-rich for sacrificial outdoor protection, epoxy as a moisture and chemical barrier. Colour: RAL code or black.", "m": null, "cost": 2}, {"name": "Blast, prime and paint", "text": "BLAST CLEAN TO ISO 8501 Sa 2.5.\n[ETCH PRIME 10-20 µm | ZINC-RICH PRIMER 75-100 µm | EPOXY PRIMER].\nPAINT [RAL xxxx | BLACK], 75-100 µm DRY.\nTHREADS TO BE PRIMED BUT FREE FROM PAINT.", "c": "Wet-applied alternative to powder coat. Keep threads free of paint. Primer: etch for adhesion (indoor), zinc-rich for sacrificial outdoor protection, epoxy as a moisture and chemical barrier. Colour: RAL code or black.", "m": null, "cost": 2}, {"name": "Thermal zinc spray", "text": "BLAST CLEAN TO ISO 8501 Sa 2.5.\nTHERMAL ZINC SPRAY 60 µm DFT [AND POWDER COAT BLACK].", "c": "Sprayed zinc gives long-life sacrificial protection for outdoor steel. Slower and dearer than primer.", "m": null, "cost": 3}, {"name": "Zinc phosphate + powder coat", "text": "ZINC PHOSPHATE AND [BLACK | GREY | BLUE] POWDER COAT", "c": "Phosphate under the powder improves adhesion and corrosion life. Colour: give a RAL code if the shade matters.", "m": null, "cost": 2}, {"name": "Zinc-rich primer + polyester top coat", "text": "ZINC-RICH POWDER PRIMER AND POLYESTER POWDER TOP COAT", "c": "Zinc-rich primer under a polyester top coat for the longest corrosion life of the powder systems.", "m": null, "cost": 3}]},
      {"id": "n2_8", "topic": "Protective coating", "text": "PROTECTIVE COATING TO REMAIN ON COMPONENT AFTER MANUFACTURE.", "c": "Leaves the supplied protective coating in place. State which coating.", "m": [], "cost": 1, "types": []},
      {"id": "n2_9", "topic": "Supplied oiled", "text": "PART TO BE SUPPLIED [LIGHTLY] OILED [TO PREVENT CORROSION].", "c": "Low-cost temporary protection for bare steel. Degrease before bonding or coating.", "m": [{"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}, {"t": "tool-steel", "label": "Tool steels"}], "cost": 1, "types": []}
    ]},
    {"id": "s3", "num": 3, "title": "Heat treatment and hardness", "notes": [
      {"id": "n3_1", "topic": "Case hardening and nitriding", "text": null, "c": "Carburise for deep case and high loads, induction for local areas, nitride for minimum distortion.", "m": [], "cost": 3, "types": [{"name": "Carburise, case harden and temper", "text": "CARBURISE, CASE HARDEN AND TEMPER TO EFFECTIVE CASE DEPTH [].\nCASE HARDNESS [], CORE HARDNESS [].\n[HANG SHAFT VERTICALLY FROM A SUITABLE EYE-BOLT.]", "c": "Hard case over a tough core for gears and shafts. It distorts, so leave a grind allowance. State effective case depth, case and core hardness.", "m": [{"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}], "cost": 3}, {"name": "Gear teeth case harden", "text": "CASE HARDEN GEAR TEETH TO EFFECTIVE CASE DEPTH [] AFTER GRINDING.\nCHAMFER OR DEBURR GEAR TOOTH SIDE EDGES 0.2 mm MAX.\nGEAR AND SPLINE PROFILES TO BE MANUFACTURED FROM TABLE DATA.", "c": "Case depth is quoted after grinding. Deburr gear tooth edges.", "m": [{"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}], "cost": 3}, {"name": "Induction harden", "text": "INDUCTION HARDEN INDICATED SURFACE TO [], Rht [].", "c": "Local hardening of marked surfaces with little overall distortion.", "m": [{"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}], "cost": 2}, {"name": "Nitride", "text": "NITRIDE.\nCOMPOUND LAYER [].\nHARDNESS [].\nNITRIDED CASE DEPTH [].\nALL DIMENSIONS APPLY AFTER HEAT TREATMENT.", "c": "Low-temperature process with the least distortion and a thin hard case. Machine to size first.", "m": [{"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}, {"t": "tool-steel", "label": "Tool steels"}], "cost": 3}]},
      {"id": "n3_2", "topic": "Hardening and tempering", "text": null, "c": "Match the process to the substrate and the final hardness.", "m": [], "cost": 2, "types": [{"name": "Harden and temper (AMS 2759)", "text": "HARDEN AND TEMPER TO AMS 2759/[1 | 2 | 3 | 4 | 5] TO HARDNESS [].", "c": "AMS 2759 slash sheet by substrate: /1 carbon and low-alloy steel below 220 ksi (1517 MPa); /2 low-alloy steel 220 ksi and above; /3 precipitation-hardening CRES, maraging and secondary-hardening steel; /4 austenitic CRES; /5 martensitic CRES.", "m": [{"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}, {"t": "stainless-steel", "label": "Stainless steels"}, {"t": "tool-steel", "label": "Tool steels"}], "cost": 2}, {"name": "Pre-grind hardening", "text": "HEAT TREAT TO HARDNESS GREATER THAN [] BEFORE GRINDING.", "c": "Harden first so distortion is ground out. Allow grind stock.", "m": [{"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}, {"t": "tool-steel", "label": "Tool steels"}], "cost": 2}, {"name": "Quench and temper", "text": "QUENCH AND TEMPER TO [].", "c": "Through-hardens to a strength level; tempering sets the final hardness.", "m": [{"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}], "cost": 2}, {"name": "Vacuum harden", "text": "VACUUM NORMALISE (920 °C).\nVACUUM HARDEN (870 °C), TEMPER AT 300 °C FOR 2 HOURS TO ACHIEVE A SURFACE HARDNESS OF [].", "c": "Clean, bright and low distortion. Suits tool steels.", "m": [{"t": "tool-steel", "label": "Tool steels"}], "cost": 3}, {"name": "Precipitation harden (17-4PH)", "text": "HEAT TREAT TO CONDITION [H900 | H1025] TO AMS 2759/3 [TO ACHIEVE A SURFACE HARDNESS OF []].\nSOLUTION TREAT AT 1024-1052 °C FOR 3 MINUTES PER 2.5 mm OF MATERIAL THICKNESS.\n[H1025: A DIMENSIONAL CONTRACTION OF 0.0004-0.001 mm/mm WILL OCCUR ON HARDENING.]", "c": "Low-distortion age hardening after solution treatment. Condition sets strength: H900 highest, H1025 tougher.", "m": [{"t": "stainless-steel", "label": "Precipitation-hardening stainless steels", "g": ["17-4PH", "15-5PH", "17-7PH"]}], "cost": 3}]},
      {"id": "n3_3", "topic": "Hardness check", "text": "CHECK HARDNESS WHERE SHOWN [OR ON EITHER END FACE] TO BE [].\nREMOVE ANY RAISED MATERIAL.", "c": "Quick check of heat treatment condition. State where to test and remove raised material around the indent. Give the scale: HRB for softer metals such as aluminium castings, HRC for hardened steels.", "m": [{"t": null, "label": "All metals", "metals": true}], "cost": 1, "types": []},
      {"id": "n3_4", "topic": "Stress relief", "text": "STRESS RELIEVE [BEFORE MACHINING] AT [] °C FOR [] HOURS MIN.", "c": "Relieves machining or weld stress before final machining so the part holds size.", "m": [{"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}, {"t": "tool-steel", "label": "Tool steels"}], "cost": 1, "types": []}
    ]},
    {"id": "s4", "num": 4, "title": "Inspection and NDT", "notes": [
      {"id": "n4_1", "topic": "Composite ultrasonic NDT", "text": "NDT INCLUDING 100% SURFACE INSPECTION AND ULTRASONIC PHASED ARRAY INSPECTION TO EVALUATE THE QUALITY OF THE COMPOSITE LAMINATE, TO BE PERFORMED ON 20% OF THE BATCH.\nDEFECT ACCEPTANCE CRITERIA [].", "c": "Phased array ultrasonics finds delamination in laminates. Testing a 20% sample keeps cost down.", "m": [{"t": "composites", "label": "Composites"}], "cost": 4, "types": []},
      {"id": "n4_2", "topic": "Crack detection (NDT)", "text": null, "c": "FPI for any non-porous metal. MPI for magnetic steels only.", "m": [], "cost": 2, "types": [{"name": "Fluorescent penetrant (FPI)", "text": "FLUORESCENT PENETRANT INSPECTION TO ASTM E1417, TYPE I, METHOD D, SENSITIVITY LEVEL 2 OR TYPE I, METHOD A, SENSITIVITY LEVEL 3.\nNO CRACK ALLOWED.", "c": "Finds surface-breaking cracks on any non-porous material. Surface must be clean and unsmeared.", "m": [{"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}, {"t": "stainless-steel", "label": "Stainless steels"}, {"t": "tool-steel", "label": "Tool steels"}, {"t": "aluminum", "label": "Aluminium alloys"}, {"t": "magnesium", "label": "Magnesium alloys"}, {"t": "titanium", "label": "Titanium alloys"}, {"t": "copper-alloy", "label": "Copper alloys"}], "cost": 2}, {"name": "Magnetic particle (MPI)", "text": "MAGNETIC PARTICLE INSPECTION (WET FLUORESCENT) TO ASTM E1444.\nRATEABLE INDICATION SIZE 0.4 mm.\nNO CRACK OF ANY SIZE ALLOWED.\nNO LINEAR INDICATION OF 0.4 mm OR GREATER ALLOWED.\nNO NON-METALLIC INCLUSION OF 0.4 mm OR GREATER ALLOWED.", "c": "Ferromagnetic materials only, so not austenitic stainless, aluminium or titanium. Finds surface and near-surface flaws.", "m": [{"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}, {"t": "tool-steel", "label": "Tool steels"}, {"t": "stainless-steel", "label": "Magnetic stainless steels", "g": ["17-4PH", "15-5PH", "17-7PH"]}], "cost": 2}]},
      {"id": "n4_3", "topic": "Defect acceptance (castings)", "text": "DEFECT ACCEPTANCE CRITERIA TO AMS 2175, GRADE [C], CLASS [4].", "c": "Sets accepted porosity and surface defects for castings. AMS 2175 Class 1 is the most critical class and Class 4 the least; Grade A is the strictest acceptance and D the most lenient. Match the class to the load path.", "m": [{"t": "aluminum", "label": "Aluminium alloys"}, {"t": "magnesium", "label": "Magnesium alloys"}, {"t": "copper-alloy", "label": "Copper alloys"}], "cost": 2, "types": []},
      {"id": "n4_4", "topic": "Pressure test (casting leak)", "text": "PRESSURE TEST TO 1 bar [UNDERWATER].\nNO BUBBLES TO BE DETECTED.", "c": "Leak test for cast fluid housings. Underwater makes bubbles visible.", "m": [{"t": "aluminum", "label": "Aluminium alloys"}, {"t": "magnesium", "label": "Magnesium alloys"}], "cost": 2, "types": []}
    ]},
    {"id": "s5", "num": 5, "title": "Part marking and identification", "notes": [
      {"id": "n5_1", "topic": "Marking: serial numbers", "text": "SERIAL NUMBERS TO BE SPECIFIED BY [].", "c": "Traceability. Name who issues the serial numbers.", "m": [], "cost": 1, "types": []},
      {"id": "n5_2", "topic": "Marking: casting", "text": null, "c": "Marks formed by the casting tool.", "m": [{"t": "aluminum", "label": "Aluminium alloys"}, {"t": "magnesium", "label": "Magnesium alloys"}, {"t": "copper-alloy", "label": "Copper alloys"}], "cost": 1, "types": [{"name": "Batch number cast in", "text": "BATCH NUMBER TO BE CAST IN THE IDENTIFIED LOCATION.", "c": "Cast-in traceability mark. Needs a feature in the mould or pattern, so it cannot be added later.", "m": [{"t": "aluminum", "label": "Aluminium alloys"}, {"t": "magnesium", "label": "Magnesium alloys"}, {"t": "copper-alloy", "label": "Copper alloys"}], "cost": 1}]},
      {"id": "n5_3", "topic": "Marking: injection moulding", "text": null, "c": "Marks formed in the mould, so every part carries them.", "m": [], "cost": 1, "types": [{"name": "Date insert", "text": "USE A DUAL-RING DATING INSERT (12 MONTHS, 25 YEARS + ARROW) FLUSH IN THE IDENTIFIED LOCATION.", "c": "Moulded-in month and year for traceability. Show the location on the drawing.", "m": [{"t": "insulating-materials", "label": "Polymers and insulators"}, {"t": "insulating-materials", "label": "Polymers (printable)"}], "cost": 1}, {"name": "Laser engraved mould", "text": "PART TO BE MARKED USING LASER ENGRAVING ON THE MOULD IN THE IDENTIFIED LOCATION.\nTYPE SIZE 1.9 mm.", "c": "Mark is part of the mould surface, so every part carries it.", "m": [{"t": "insulating-materials", "label": "Polymers and insulators"}, {"t": "insulating-materials", "label": "Polymers (printable)"}], "cost": 1}, {"name": "Underflush insert", "text": "PART NUMBER TO BE ENGRAVED UNDERFLUSH USING AN INSERT IN THE IDENTIFIED LOCATION.\nTYPE SIZE [1.5 | 4] mm.", "c": "Mould insert gives a permanent mark. Type size is set by the insert: 1.5 mm on small parts, 4 mm where space allows.", "m": [{"t": "insulating-materials", "label": "Polymers and insulators"}, {"t": "insulating-materials", "label": "Polymers (printable)"}, {"t": "composites", "label": "Composites"}], "cost": 1}]},
      {"id": "n5_4", "topic": "Marking: label", "text": null, "c": "Use where a direct mark is not possible, such as coated, moulded or delicate parts.", "m": [], "cost": 1, "types": [{"name": "Dymo label", "text": "PART TO BE IDENTIFIED USING A DYMO LABEL IN THE IDENTIFIED LOCATION.\nLABEL SHALL STATE THE PART NUMBER, REVISION, AND BATCH OR LOT NUMBER.", "c": "Label-maker tape. Quick and low cost. Durability is limited on hot, oily or rough surfaces.", "m": null, "cost": null}, {"name": "Printed label", "text": "PART TO BE IDENTIFIED USING A PRINTED LABEL IN THE IDENTIFIED LOCATION.\nLABEL SHALL STATE THE PART NUMBER, REVISION, AND BATCH OR LOT NUMBER.", "c": "Printed per batch, so revision and lot can change without tooling. Durability depends on the label stock.", "m": null, "cost": null}, {"name": "Self-adhesive label", "text": "PART TO BE IDENTIFIED USING A SELF-ADHESIVE LABEL IN THE IDENTIFIED LOCATION.\nLABEL SHALL STATE THE PART NUMBER, REVISION, AND BATCH OR LOT NUMBER.", "c": "Lowest cost. Not permanent on hot or oily surfaces.", "m": null, "cost": null}, {"name": "Self-adhesive label, wrap-around", "text": "PART TO BE IDENTIFIED USING A SELF-ADHESIVE WRAP-AROUND LABEL LOCATED MORE THAN 20 mm FROM EITHER END.\nLABEL SHALL STATE THE PART NUMBER, REVISION, AND BATCH OR LOT NUMBER.", "c": "For pipes and tubes. Keep clear of the ends so it survives cutting and fitting.", "m": null, "cost": null}]},
      {"id": "n5_5", "topic": "Marking: laser engraving", "text": null, "c": "Fast and permanent on metals.", "m": [{"t": null, "label": "All metals", "metals": true}], "cost": 1, "types": [{"name": "Laser engrave", "text": "PART NUMBER AND REVISION [AND SERIAL NUMBER] TO BE LASER ENGRAVED [TO AS478 15B3] IN THE IDENTIFIED LOCATION.\nENGRAVING DETAILS: ARIAL FONT, 4 mm FONT HEIGHT, 0.2 mm ETCHING DEPTH.", "c": "Fast, permanent and works on hardened or coated surfaces. Shallow, so mark before coating if it must stay visible. AS478 method 15 = laser: 15A dot matrix, 15B continuous engrave; suffix 1/2/3 = shallow/intermediate/deep. 15B3 = 0.1 mm to 0.25 mm.", "m": [{"t": null, "label": "All metals", "metals": true}], "cost": 1}]},
      {"id": "n5_6", "topic": "Marking: machining", "text": null, "c": "Engraved in the CNC set-up.", "m": [{"t": null, "label": "All metals", "metals": true}], "cost": 1, "types": [{"name": "Machine engrave", "text": "PART NUMBER AND REVISION [AND SERIAL NUMBER] TO BE MACHINE ENGRAVED [TO AS478 3B2] IN THE IDENTIFIED LOCATION.\nENGRAVING DETAILS: ARIAL FONT, 4 mm FONT HEIGHT, 60° ENGRAVING TOOL, 0.15 mm MAX ETCHING DEPTH.", "c": "Cut in the same set-up on the CNC. Tool size limits the font size. AS478 method 3B = CNC engrave: 3B1 shallow 0.013 mm to 0.08 mm, 3B2 deep 0.05 mm to 0.15 mm.", "m": [{"t": null, "label": "All metals", "metals": true}], "cost": 1}]},
      {"id": "n5_7", "topic": "Marking: pen", "text": "PEN MARK IN PERMANENT INK TO BE APPLIED IN THE IDENTIFIED LOCATION.\nMARKING SHALL STATE PART NUMBER, REVISION, AND BATCH OR LOT NUMBER.", "c": "Quick mark on finished assemblies where engraving or a label is impractical.", "m": [], "cost": 1, "types": []}
    ]},
    {"id": "s6", "num": 6, "title": "Cutting, forming and machining", "notes": [
      {"id": "n6_1", "topic": "Flat pattern", "text": "FLAT PATTERN TO BE CUT TO 2D DXF.", "c": "Flat blank is cut from the DXF, bends added after.", "m": [{"t": "aluminum", "label": "Aluminium alloys"}, {"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}, {"t": "stainless-steel", "label": "Stainless steels"}, {"t": "copper-alloy", "label": "Copper alloys"}], "cost": 2, "types": []},
      {"id": "n6_2", "topic": "Enamel stripping (wire)", "text": "MINIMUM WIRE DIAMETER AFTER ENAMEL STRIPPING IS [] mm.\nMEASURE STRIPPED WIRE DIAMETER WITH MICROMETER.", "c": "Minimum wire diameter is measured after the enamel is stripped.", "m": [{"t": "copper-alloy", "label": "Copper alloys"}], "cost": 2, "types": []},
      {"id": "n6_3", "topic": "Machining allowance", "text": null, "c": "Allow stock where a later process moves or hardens the surface.", "m": [{"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}, {"t": "stainless-steel", "label": "Stainless steels"}, {"t": "tool-steel", "label": "Tool steels"}], "cost": 2, "types": [{"name": "Grinding allowance", "text": "LEAVE ALLOWANCE FOR GRINDING ON SURFACES MARKED \"G\".\nFINISH GRIND TO TOLERANCE.", "c": "Grind for tight size and finish on hardened surfaces.", "m": null, "cost": 3}, {"name": "Rough machine, leave 5 mm", "text": "ROUGH MACHINE LEAVING 5 mm ON DIAMETERS AND FACES, THEN FINISH MACHINE.", "c": "Rough before heat treatment or stress relief, finish after.", "m": null, "cost": 2}]},
      {"id": "n6_4", "topic": "Magnet machining", "text": "MATERIAL TO BE REMOVED IS MAGNETIC (MAGNET GRADE []).\nFLOOD COOLANT MUST BE USED.\nONLY THE FEATURES DEFINED BY DATUMS [] SHALL BE USED TO MOUNT THE PART.\nSTORE IN PROVIDED PACKAGING.\nWRAP GROUND SURFACE IN VIKING PROTECTIVE TAPE.", "c": "NdFeB and SmCo are brittle and magnetic. Use flood coolant, fixture on datums only and expect specialist grinding. Swarf is a fire risk.", "m": [{"t": "magnets", "label": "Magnets"}], "cost": 5, "types": []},
      {"id": "n6_5", "topic": "PEM inserts", "text": "PEM INSERT TO BE INSTALLED AFTER FORMING WHERE POSSIBLE.\nINSTALLATION FORCE [] kN.\nINSTALL USING PUNCH (PEM PART NUMBER []) AND ANVIL (PEM PART NUMBER []).", "c": "Install after forming. Check hole size and sheet hardness against the insert.", "m": [{"t": "aluminum", "label": "Aluminium alloys"}, {"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}, {"t": "stainless-steel", "label": "Stainless steels"}], "cost": 2, "types": []},
      {"id": "n6_6", "topic": "Profile cutting", "text": null, "c": "Laser for thin sheet, waterjet for thick or heat-sensitive material, EDM for fine detail, stamping or die cutting for volume.", "m": [], "cost": 2, "types": [{"name": "Blade cutting", "text": "PART TO BE MANUFACTURED BY BLADE CUTTING FROM 2D DXF DATA.\nU.O.S. PROFILE 0.4 A B C.", "c": "Thin soft sheet such as insulation. Use waterjet where a blade will not cut.", "m": [{"t": "insulating-materials", "label": "Polymers and insulators"}, {"t": "composites", "label": "Composites"}], "cost": 2}, {"name": "Die cutting", "text": "PART TO BE MANUFACTURED BY DIE CUTTING FROM 2D DXF DATA.\nU.O.S. PROFILE 0.4 A B C.", "c": "Flat soft sheet cut to a tool profile. Needs a die, so suits volume runs of thin insulation and gasket material.", "m": [{"t": "insulating-materials", "label": "Polymers and insulators"}, {"t": "composites", "label": "Composites"}], "cost": 2}, {"name": "EDM", "text": "PART TO BE MANUFACTURED BY EDM CUTTING FROM 2D DXF DATA.\nU.O.S. PROFILE 0.4 A B C.", "c": "Tight tolerance and hard materials with no cutting force. Conductive only, slow and costly.", "m": [{"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}, {"t": "stainless-steel", "label": "Stainless steels"}, {"t": "tool-steel", "label": "Tool steels"}, {"t": "titanium", "label": "Titanium alloys"}, {"t": "copper-alloy", "label": "Copper alloys"}, {"t": "aluminum", "label": "Aluminium alloys"}], "cost": 4}, {"name": "Laser", "text": "PART TO BE MANUFACTURED BY LASER CUTTING FROM 2D DXF DATA.\nU.O.S. PROFILE 0.4 A B C.", "c": "Fast and low cost for thin to medium sheet. Edges are heat affected and can carry dross or taper on thick plate. Note secondary operations on the drawing (deburr, tap, countersink).", "m": [{"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}, {"t": "stainless-steel", "label": "Stainless steels"}, {"t": "aluminum", "label": "Aluminium alloys"}, {"t": "copper-alloy", "label": "Copper alloys"}, {"t": "titanium", "label": "Titanium alloys"}], "cost": 2}, {"name": "Stamping", "text": "PART TO BE MANUFACTURED BY STAMPING FROM 2D DXF DATA.\nU.O.S. PROFILE 0.4 A B C.", "c": "Lowest part cost in volume but needs a tool. Suits laminations and flat parts.", "m": [{"t": "aluminum", "label": "Aluminium alloys"}, {"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}, {"t": "stainless-steel", "label": "Stainless steels"}, {"t": "copper-alloy", "label": "Copper alloys"}, {"t": "electrical-steel", "label": "Electrical steel"}], "cost": 1}, {"name": "Waterjet", "text": "PART TO BE MANUFACTURED BY WATERJET CUTTING FROM 2D DXF DATA.\nU.O.S. PROFILE 0.4 A B C.", "c": "No heat-affected zone, so suits thick, reflective or heat-sensitive material and laminates. Slower than laser, with more edge taper.", "m": [{"t": null, "label": "All metals", "metals": true}, {"t": "insulating-materials", "label": "Polymers and insulators"}, {"t": "composites", "label": "Composites"}, {"t": "electrical-steel", "label": "Electrical steel"}], "cost": 3}]},
      {"id": "n6_7", "topic": "Splines", "text": "SPLINE MUST BE MANUFACTURED USING TABULATED DATA.\nALL OTHER FEATURES MAY BE MACHINED USING 3D CAD DATA.\nSPLINES TO MATE WITH GO AND NO-GO GAUGE.", "c": "Form checks with go and no-go gauges need tabulated data. 3D geometry alone is not enough to inspect.", "m": [{"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}, {"t": "stainless-steel", "label": "Stainless steels"}, {"t": "tool-steel", "label": "Tool steels"}], "cost": 3, "types": []},
      {"id": "n6_8", "topic": "Welding", "text": null, "c": "Arc welding for fabrications, ultrasonic for conductor tabs.", "m": [], "cost": 3, "types": [{"name": "Fabrication welding", "text": "GRIND FLAT ANY BURRS OR WELD SPATTER.", "c": "Grind burrs and spatter flat after welding.", "m": [{"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}, {"t": "stainless-steel", "label": "Stainless steels"}, {"t": "aluminum", "label": "Aluminium alloys"}], "cost": 3}, {"name": "Ultrasonic weld (tab)", "text": "TAB TO BE ULTRASONICALLY WELDED AND TESTED IN ACCORDANCE WITH [].", "c": "Solid-state joint for tabs and conductors. State the test specification.", "m": [{"t": "copper-alloy", "label": "Copper alloys"}], "cost": 3}]}
    ]},
    {"id": "s7", "num": 7, "title": "Casting and forging", "notes": [
      {"id": "n7_1", "topic": "Casting specification", "text": "CAST DIMENSIONAL TOLERANCES TO ISO 8062-3 DCTG [8 OR BETTER | 9].\nCAST GEOMETRICAL TOLERANCES TO ISO 8062-3 GCTG 8 OR BETTER.\nCASTING ROUGHNESS TO ISO 1302 N10 OR BETTER.\nUNLESS STATED, DRAFT ANGLES AS PER 3D CAD DATA ([2 | 3]° MIN).\nHEAT TREAT AS INDICATED, CONDITION T6.\nKEEP FEEDS, EJECTION POINTS ETC. AWAY FROM FEATURES USED TO DEFINE DATUMS.\nMONTH AND YEAR OF MANUFACTURE TO BE MARKED USING A DATE INSERT IN THE CAST TOOLING AT THE LOCATION INDICATED.\nSEE CASTING DRAWING FOR COMPLETE DEFINITION OF CAST DATUMS X, Y, Z.", "c": "ISO 8062-3 sets dimensional (DCTG) and geometrical (GCTG) casting grades. A lower (tighter) grade costs more; check it suits the casting process. Draft: 2° outside faces, 3° inside faces or deep pockets.", "m": [{"t": "aluminum", "label": "Aluminium alloys"}, {"t": "magnesium", "label": "Magnesium alloys"}, {"t": "copper-alloy", "label": "Copper alloys"}], "cost": 3, "types": []},
      {"id": "n7_2", "topic": "Forging", "text": "FORGING TOLERANCES GRADE F TO EN 10243-1.\nSTEEL CATEGORY M2.\nMAKE FROM FORGING [].", "c": "Grade F is the standard EN 10243-1 tolerance grade (E is closer). Forge tooling adds cost.", "m": [{"t": "steel-carbon-alloy", "label": "Carbon and alloy steels"}], "cost": 4, "types": []},
      {"id": "n7_3", "topic": "Machined from casting", "text": "PART TO BE MACHINED FROM CASTING [].\n[MACHINING ALLOWANCE TYPICALLY 3 mm.]\n[SETUP REFERENCING CAST SURFACE DATUM D.]\nPATTERN CAN BE MACHINED USING 3D CAD DATA.", "c": "Set up from the cast datum. Leave machining allowance on cast surfaces.", "m": [{"t": "aluminum", "label": "Aluminium alloys"}, {"t": "magnesium", "label": "Magnesium alloys"}, {"t": "copper-alloy", "label": "Copper alloys"}], "cost": 3, "types": []}
    ]},
    {"id": "s8", "num": 8, "title": "3D printing", "notes": [
      {"id": "n8_1", "topic": "3D printing: FDM", "text": null, "c": "Extruded filament. Layer lines and weaker in Z. Profile 0.6 is about ±0.3 mm.", "m": [{"t": "insulating-materials", "label": "Polymers (printable)"}], "cost": 2, "types": [{"name": "Antero 800NA (PEKK)", "text": "PART TO BE MANUFACTURED BY FDM FROM 3D CAD DATA.\nU.O.S. PROFILE 0.6.\nU.O.S. MATERIAL: ANTERO 800NA (PEKK-BASED) - FDM.", "c": "High temperature and chemical resistance.", "m": [{"t": "insulating-materials", "label": "Polymers (printable)", "g": ["peek"]}], "cost": 4}, {"name": "PA12 nylon", "text": "PART TO BE MANUFACTURED BY FDM FROM 3D CAD DATA.\nU.O.S. PROFILE 0.6.\nU.O.S. MATERIAL: PA12 NYLON - FDM.", "c": "Tough nylon. Needs a heated chamber and dry filament to avoid warping.", "m": [{"t": "insulating-materials", "label": "Polymers (printable)", "g": ["polyamide"]}], "cost": 3}, {"name": "PETG", "text": "PART TO BE MANUFACTURED BY FDM FROM 3D CAD DATA.\nU.O.S. PROFILE 0.6.\nU.O.S. MATERIAL: PETG - FDM.", "c": "Lowest cost and tough. Softens at modest temperature.", "m": [{"t": "insulating-materials", "label": "Polymers (printable)", "g": ["polyester (pet)"]}], "cost": 2}]},
      {"id": "n8_2", "topic": "3D printing: MJF", "text": null, "c": "Powder bed with a fusing agent. Finer, more uniform surface than SLS and faster batches. Profile 0.6 is about ±0.3 mm.", "m": [{"t": "insulating-materials", "label": "Polymers (printable)"}], "cost": 3, "types": [{"name": "PA12 nylon", "text": "PART TO BE MANUFACTURED BY MJF FROM 3D CAD DATA.\nU.O.S. PROFILE 0.6.\nU.O.S. MATERIAL: PA12 NYLON - MJF.", "c": "Standard functional nylon.", "m": [{"t": "insulating-materials", "label": "Polymers (printable)", "g": ["polyamide"]}], "cost": 3}]},
      {"id": "n8_3", "topic": "3D printing: SLS", "text": null, "c": "Powder bed needs no supports, so complex shapes are easy. Slightly grainy surface. Profile 0.6 is about ±0.3 mm.", "m": [{"t": "insulating-materials", "label": "Polymers (printable)"}], "cost": 3, "types": [{"name": "PA12 nylon", "text": "PART TO BE MANUFACTURED BY SLS FROM 3D CAD DATA.\nU.O.S. PROFILE 0.6.\nU.O.S. MATERIAL: PA12 NYLON - SLS, COLOUR NATURAL.", "c": "Standard functional nylon.", "m": [{"t": "insulating-materials", "label": "Polymers (printable)", "g": ["polyamide"]}], "cost": 3}, {"name": "Nylon, glass filled 30% min", "text": "PART TO BE MANUFACTURED BY SLS FROM 3D CAD DATA.\nU.O.S. PROFILE 0.6.\nU.O.S. MATERIAL: NYLON, GLASS FILLED 30% MIN - SLS, COLOUR NATURAL.", "c": "Stiffer and more heat resistant than unfilled, but more brittle and abrasive.", "m": [{"t": "insulating-materials", "label": "Polymers (printable)", "g": ["polyamide"]}], "cost": 3}, {"name": "PA66 nylon", "text": "PART TO BE MANUFACTURED BY SLS FROM 3D CAD DATA.\nU.O.S. PROFILE 0.6.\nU.O.S. MATERIAL: PA66 NYLON - SLS, COLOUR NATURAL.", "c": "Higher temperature capability than PA12. Absorbs moisture and shrinks more.", "m": [{"t": "insulating-materials", "label": "Polymers (printable)", "g": ["polyamide"]}], "cost": 3}]}
    ]},
    {"id": "s9", "num": 9, "title": "Moulding, composites and VPI", "notes": [
      {"id": "n9_1", "topic": "Composite sleeves and laminates", "text": null, "c": "Carbon for strength and stiffness, glass where conductivity matters.", "m": [{"t": "composites", "label": "Composites"}], "cost": 3, "types": [{"name": "CFRP sleeve", "text": "100 gsm UD CARBON FIBRE PRE-PREG: 12K TORAY T800 CARBON FIBRE, TB CARBON HP200 EPOXY RESIN.\nCERTIFICATE OF CONFORMITY MUST BE PROVIDED.\nCURE: ROOM TEMPERATURE TO 120 °C AT 2.5 °C/min; DWELL 60 MINUTES; RISE TO 190 °C AT 1 °C/min; DWELL 120 MINUTES; COOL TO 60 °C WITH OVEN DOOR CLOSED.\nPART TO BE MADE BY AUTOMATED TAPE PLACEMENT, TAPE WIDTH [] mm, HELIX ANGLE [] °.\nWINDING MANDREL MUST BE APPROVED BY [COMPANY] BEFORE USE ON PRODUCTION PARTS.\nANY CHANGE TO THE TOOLING SHALL BE COMMUNICATED AND AGREED BY [COMPANY].\nSTART AND FINISH LOCATION MUST BE AWAY FROM THE FINISHED PART.\nWOUND TUBE LENGTH MUST EXCEED THE FINISHED PART SIZE AND BE MACHINED DOWN TO LENGTH.", "c": "Highest stiffness and strength for retention sleeves. Conductive, so eddy-current loss near magnets.", "m": null, "cost": 4}, {"name": "E-glass sleeve", "text": "MATERIAL MUST BE IN-DATE AND IN-LIFE, STORED IN ACCORDANCE WITH MANUFACTURER INSTRUCTIONS.\nMATERIAL: E-GLASS WOVEN 7781 STYLE TO AMS-C-9084 VIII-B CLASS 2 (MECHANICAL PROPERTIES WITHIN 3%, WITH FST PROPERTIES CONFORMING TO UL94 V-1 AT PART THICKNESS).\nLAYUP: [0/90, ±45, ±45, 0/90] (QUASI-ISOTROPIC) WITH PEEL PLY ON OUTER FACE.\nINITIAL LAYUP TO EXCEED PART LENGTH ON TABBED END.\nMOULD TO SIZE ON PLAIN END.\nDIMENSIONS APPLY AFTER PEEL-PLY REMOVAL.\nCURE: VACUUM BAG ON CYLINDRICAL MANDREL; ROOM TEMPERATURE TO 120 °C AT 2-3 °C/min; DWELL >60 MINUTES; COOL TO ROOM TEMPERATURE AT 2-3 °C/min; Tg MUST BE ABOVE 100 °C.\nFINISHING: CUT PART TO LENGTH AND REMOVE PEEL PLY (HAND TRIM ACCEPTABLE).", "c": "Non-conductive and lower cost than carbon, with lower strength. No eddy-current loss.", "m": null, "cost": 3}, {"name": "G11 laminate", "text": "PART TO BE PRODUCED FROM VON ROLL VETRONIT G11 LAMINATE (FINE WEAVE GLASS FABRIC BONDED WITH EPOXY RESIN).", "c": "Epoxy glass-fabric laminate: a machinable insulator.", "m": null, "cost": 2}, {"name": "GRP pre-preg", "text": "UNIDIRECTIONAL GLASS FIBRE PRE-PREG, S-GLASS 160 gsm, SHD MTC400-1 EPOXY, RESIN WEIGHT 38%.\nPART TO BE MADE ON A POWERED PLATEN ROLLING PRESS, 3 PLY, THEORETICAL THICKNESS 0.144 mm.", "c": "Unidirectional S-glass wrap for high-strength insulating layers.", "m": null, "cost": 3}]},
      {"id": "n9_2", "topic": "Injection moulding: general", "text": "DRAFT ANGLES AS PER STEP FILE.\nALL EJECTOR PINS TO BE FLUSH OR UNDERFLUSH BY 0.127 mm.\nSINK MARKS, FLASH, WELD LINES AND SCRATCHES TO BE KEPT TO A MINIMUM (NON-COSMETIC PART).\nINJECTION GATE AND EJECTOR PIN LOCATIONS TO BE APPROVED BY [] PRIOR TO TOOL BUILD.", "c": "Draft follows the STEP file so the part releases. Pins sit flush or underflush so marks do not stand proud. Non-cosmetic part: sink marks, flash and weld lines are kept to a minimum rather than eliminated. Gate and ejector pin positions leave marks, so agree them before tool build.", "m": [{"t": "insulating-materials", "label": "Polymers and insulators"}], "cost": 3, "types": []},
      {"id": "n9_3", "topic": "Seal and gap pad material", "text": null, "c": "EPDM for sealing, gap pad for thermal contact.", "m": [{"t": "insulating-materials", "label": "Polymers and insulators"}], "cost": 2, "types": [{"name": "EPDM seal", "text": "EPDM SEAL TO ISO 3601-3 AND DIN 3771-4 TYPE N, -40 TO 120 °C CONTINUOUS, 150 °C PEAK.", "c": "Suits water-glycol coolant and weather. Poor with mineral oil and fuel.", "m": null, "cost": 2}, {"name": "Gap pad", "text": "GAP PAD HARDNESS 15 SHORE 00, -40 TO 200 °C CONTINUOUS.", "c": "Soft thermal interface that fills tolerance gaps against a heat sink.", "m": null, "cost": 2}, {"name": "Gap pad (Keratherm Softtherm)", "text": "MATERIAL: KERATHERM SOFTTHERM 86/325\nTHERMAL PROPERTIES:\nTHERMAL RESISTANCE =\n0.82 K/W AT 1 mm COMPRESSED TO 0.99 mm\n0.41 K/W AT 1 mm COMPRESSED TO 0.5 mm\nTHERMAL IMPEDANCE = 164 °C mm/W (0.25 K in²/W)\nTHERMAL CONDUCTIVITY = 3 W/mK\nELECTRICAL PROPERTIES:\nBREAKDOWN VOLTAGE = 6 kV\nDIELECTRIC BREAKDOWN = 12 kV/mm\nVOLUME RESISTIVITY = 85.4 GΩ cm\nDIELECTRIC LOSS FACTOR = 0.145\nDIELECTRIC CONSTANT = 3.77\nMECHANICAL PROPERTIES:\nMEASURED THICKNESS = 1.5 mm\nSHORE HARDNESS = 35-50 SHORE 00\nYOUNG'S MODULUS = 32 N/cm²\nPHYSICAL PROPERTIES:\nDENSITY = 1.95 g/cm³\nAPPLICATION TEMPERATURE = -40 TO +180 °C\nFLAME CLASS = UL94 V-0\nTOTAL MASS LOSS < 0.35 % BY MASS", "c": "Specific pad: 3 W/mK, 35-50 Shore 00, -40 to +180 °C, UL94 V-0. The note lists thermal, electrical, mechanical and physical properties.", "m": null, "cost": 2}]},
      {"id": "n9_4", "topic": "VPI: DC withstand", "text": "AFTER CURE, ONCE THE PART IS RETURNED TO [COMPANY], PERFORM A DC WITHSTAND TEST: CONNECT AN OHMMETER ACROSS ONE PHASE TERMINAL AND THE COOLING JACKET; APPLY 0 TO [] kV OVER A [] s RAMP; RECORD RESISTANCE ACROSS PHASE TERMINALS AND COOLING JACKET ONCE READINGS ARE STABLE; HOLD THE VOLTAGE FOR A FURTHER [] s AND TAKE A SECOND READING; REPEAT FOR THE SECOND CHANNEL AND BETWEEN BOTH POWER CHANNELS; RECORD AMBIENT CONDITIONS (PRESSURE, TEMPERATURE, HUMIDITY).\nANY READING BELOW [] GΩ REQUIRES ENGINEERING ATTENTION.", "c": "Insulation check of the stator after cure. Readings below 1 GΩ need engineering review.", "m": [{"t": "electrical-steel", "label": "Electrical steel"}, {"t": "copper-alloy", "label": "Copper alloys"}, {"t": "insulating-materials", "label": "Polymers and insulators"}], "cost": 2, "types": []},
      {"id": "n9_5", "topic": "VPI: documents", "text": "REQUIRED DOCUMENTATION: CERTIFICATE OF CONFORMITY; MATERIAL CERTIFICATE OF CONFORMITY CONTAINING RESIN PART NUMBER, BATCH NUMBER AND BATCH PROPERTIES CONFORMING TO THE MATERIAL SPECIFICATION; CURE PROFILE.", "c": "Resin batch and cure profile records for traceability.", "m": [{"t": "electrical-steel", "label": "Electrical steel"}, {"t": "copper-alloy", "label": "Copper alloys"}, {"t": "insulating-materials", "label": "Polymers and insulators"}], "cost": 1, "types": []},
      {"id": "n9_6", "topic": "VPI: masking", "text": "ALL THREADED INSERTS SHALL BE FREE OF RESIN ON BOTH THEIR INTERNAL THREADS AND EXPOSED FLAT SURFACE.\nENSURE CABLES ARE IN THE IDENTIFIED POSITIONS PRIOR TO STARTING VPI.", "c": "Keeps resin out of threads and mating faces. Check cables are positioned first.", "m": [{"t": "electrical-steel", "label": "Electrical steel"}, {"t": "copper-alloy", "label": "Copper alloys"}, {"t": "insulating-materials", "label": "Polymers and insulators"}], "cost": 2, "types": []},
      {"id": "n9_7", "topic": "VPI: resin and cycle", "text": "STATOR TO BE VACUUM PRESSURE IMPREGNATED WITH ULTIMEG U2220 EPOXY RESIN.\nWEIGH UNTOUCHED STATOR AND RECORD MASS.\nNO RESIN PERMITTED ON SURFACES MARKED WITH -----; ULTIMEG U720 PERMITTED ON INTERNAL DIAMETER OF LAMINATION STACKS AND SLOT LINER.\nPRE-HEAT STATOR AT [] °C FOR [] HOURS MIN AND ALLOW TO COOL PASSIVELY (AT AMBIENT TEMPERATURE) TO [] °C MAX PRIOR TO IMPREGNATION.\nIMPREGNATION: DRY VACUUM [] MINUTES AT [] mbar; SUBMERGE PART; WET VACUUM [] MINUTES AT [] mbar; OVERPRESSURE [] MINUTES AT [] mbar; COOL PASSIVELY TO AMBIENT TEMPERATURE.\nREMOVE ALL GREASE AND RESIN FROM STATOR INTERNAL DIAMETER AFTER CURE.\nWEIGH FINISHED ASSEMBLY TO DETERMINE IMPREGNATED RESIN MASS.", "c": "Fills winding voids for insulation and heat transfer. Pre-heat and vacuum cycle times follow the resin data.", "m": [{"t": "electrical-steel", "label": "Electrical steel"}, {"t": "copper-alloy", "label": "Copper alloys"}, {"t": "insulating-materials", "label": "Polymers and insulators"}], "cost": 4, "types": []},
      {"id": "n9_8", "topic": "VPI: visual inspection", "text": "VPI RESIN SHALL BE VISUALLY INSPECTED AFTER CURE FOR: MASKING GREASE REMOVED AND NO RESIN ON MASKED FACES AND THREADS; NO CRACKS, BLISTERING, BUBBLES, DELAMINATION, DRY SPOTS OR FLAKING; RESIN SURFACE SMOOTH AND UNIFORMLY COATED, INCLUDING END WINDINGS AND STATOR SLOTS; NO EXPOSED STATOR COMPONENTS IN NON-MASKED AREAS; NO INCLUSIONS OF ANY TYPE (E.G. DUST, OIL, MOISTURE, DEBRIS).", "c": "Post-cure check for cracks, blisters, dry spots and inclusions.", "m": [{"t": "electrical-steel", "label": "Electrical steel"}, {"t": "copper-alloy", "label": "Copper alloys"}, {"t": "insulating-materials", "label": "Polymers and insulators"}], "cost": 1, "types": []}
    ]},
    {"id": "s10", "num": 10, "title": "Laminations and magnets", "notes": [
      {"id": "n10_1", "topic": "Lamination material and coating", "text": "LAMINATION MATERIAL: COGENT NO20-1200 ELECTRICAL STEEL (0.2 mm) [OR EQUIVALENT TO EN 10303:2015] [ALTERNATIVES: M235-35A 0.35 mm; NO10].\nCOATING: REMISOL EB 549 (TRADE NAME SURALAC 9000), STANDARD THICKNESS 4.5 µm [OR EQUIVALENT TO IEC 60085 CLASS H, GRADE C3 PER ASTM A976:2008], SUPPLIED IN B-STAGE CURE.", "c": "Thin electrical steel cuts eddy-current loss. Thinner gauge costs more and is harder to handle.", "m": [{"t": "electrical-steel", "label": "Electrical steel"}], "cost": 4, "types": []},
      {"id": "n10_2", "topic": "Lamination stack (bonded)", "text": "PART TO BE MADE FROM A PRE-BONDED STACK OF [] LAMINATIONS; USE THE REQUIRED NUMBER OF [] mm LAYERS (NOMINAL) TO OBTAIN [] mm AS A COMPLETE STACK.\nBOND THE STACK TO THE LAMINATION SUPPLIER'S INSTRUCTIONS [OR VOLTATEX 1175W/1075K].\nSURFACE COATING TO KIENLE & SPIESS ISOL20.", "c": "Bonding avoids welds or rivets that short laminations. State stack height, layer count and bond cure.", "m": [{"t": "electrical-steel", "label": "Electrical steel"}], "cost": 4, "types": []},
      {"id": "n10_3", "topic": "Lamination stack cure and storage", "text": "CURE UNDER [] bar PRESSURE AT [] °C FOR NOT LESS THAN [] HOURS.\nSTORE AT [COMPANY] IN A TEMPERATURE-CONTROLLED ROOM BELOW [] °C WITH HUMIDITY [] % RELATIVE FOR A MAXIMUM OF [] MONTHS FROM MANUFACTURE DATE.", "c": "Cure under the stated pressure and temperature. B-stage stacks have a limited shelf life.", "m": [{"t": "electrical-steel", "label": "Electrical steel"}], "cost": 2, "types": []},
      {"id": "n10_4", "topic": "Magnet bond preparation", "text": "CHECK MAGNET DATE OF MANUFACTURE AND ENSURE IT IS MARKED BEFORE INSTALLATION.\nENSURE BOND SURFACES ARE CLEAN, DRY AND GREASE-FREE BEFORE APPLYING ADHESIVE: CLEAN USING IPA AND LINT-FREE WIPES; SURFACES MUST BE DRY BEFORE APPLYING ADHESIVE; MAX 5 MINS BETWEEN CLEANING AND ADHESIVE APPLICATION.", "c": "Clean, dry bond faces. Limit the time between cleaning and adhesive.", "m": [{"t": "magnets", "label": "Magnets"}], "cost": 1, "types": []},
      {"id": "n10_5", "topic": "Magnet epoxy coat", "text": "COAT WITH HIGH TEMPERATURE EPOXY (EPX 412), [150 | 180] °C CONTINUOUS OPERATING TEMPERATURE, THICKNESS 5-25 µm [COLOUR GREY].\nAPPLY ALL OVER EXCEPT WHERE MASKING IS SPECIFIED AS SHOWN.\nNO EPOXY COATING ON SURFACE IDENTIFIED.", "c": "Epoxy protects NdFeB from corrosion and insulates it. Coat thickness affects the air gap. Pick the rating (150 or 180 °C) above the magnet's maximum operating temperature.", "m": [{"t": "magnets", "label": "Magnets"}], "cost": 2, "types": []},
      {"id": "n10_6", "topic": "Magnet segments bonded", "text": "THE [] SEGMENTS (NOMINAL THICKNESS PER SEGMENT [] mm) ARE BONDED TOGETHER USING DURALCO NM25 HIGH TEMPERATURE EPOXY CONTAINING 0.1 mm GLASS BEADS, BOND LINES [] mm MIN, [] mm MAX.\nAFTER BONDING, THE MAGNET ASSEMBLY IS GROUND TO THE DIMENSIONS AND TOLERANCES SHOWN, THEN COATED WITH HIGH TEMPERATURE EPOXY.", "c": "Bonded segments cut eddy-current loss. Glass beads set the bond line thickness.", "m": [{"t": "magnets", "label": "Magnets"}], "cost": 4, "types": []},
      {"id": "n10_7", "topic": "Magnet supply and marking", "text": null, "c": "Supplied magnetised and pole-marked. Handle with non-ferrous tools.", "m": [{"t": "magnets", "label": "Magnets"}], "cost": 2, "types": [{"name": "Paint pen", "text": "PART TO BE SUPPLIED IN FULLY MAGNETISED CONDITION, WITH PAINT PEN MARKING TO IDENTIFY NORTH AND SOUTH POLES, PART NUMBER AND ISSUE.\nMARK TO IDENTIFY FROM SIMILAR MAGNETS OF DIFFERING MATERIAL AND CONSTRUCTION.", "c": "Quick, no tooling. Can rub off, and cleaning may remove it.", "m": null, "cost": 1}, {"name": "Laser marking", "text": "PART TO BE SUPPLIED IN FULLY MAGNETISED CONDITION.\nNORTH AND SOUTH POLES, PART NUMBER AND REVISION TO BE LASER MARKED AFTER EPOXY COATING IN THE IDENTIFIED LOCATION.\nMARKING DETAILS: ARIAL FONT, [] mm FONT HEIGHT.\nMARKING SHALL NOT BREACH THE EPOXY COATING.\nMARK TO IDENTIFY FROM SIMILAR MAGNETS OF DIFFERING MATERIAL AND CONSTRUCTION.", "c": "Permanent and survives cleaning. Marked on the coat without breaching it. Supplier to confirm this is achievable.", "m": null, "cost": 2}]},
      {"id": "n10_8", "topic": "Rotor stack mass", "text": "BOM QTY IS REPRESENTATIVE: MEETING THE WEIGHT REQUIREMENT BELOW TAKES PRECEDENCE.\nMINIMUM UNCURED STACK MASS [] g (INFILL []%).\nMAXIMUM UNCURED STACK MASS [] g (INFILL []%).", "c": "Mass window controls stack fill. BOM quantity is representative only.", "m": [{"t": "electrical-steel", "label": "Electrical steel"}], "cost": 1, "types": []}
    ]},
    {"id": "s11", "num": 11, "title": "Assembly and test", "notes": [
      {"id": "n11_1", "topic": "Pressure test (assembly)", "text": null, "c": "Pressure decay gives a measured result, unlike a bubble test.", "m": [], "cost": 2, "types": [{"name": "Coolant loop, 1 bar", "text": "ENSURE BOTH ADAPTOR STRAIGHT PIPE [] TO TUBE [] ARE INSTALLED.\nINJECT ATMOSPHERIC AIR CONFORMING TO ISO 8573-1:2010 CLASS [2:4:1].\nMEASURE PRESSURE VIA THE OUTLET OR MEASUREMENT PORT (SEE REAR VIEW).\nTEST PARAMETERS: PRESSURISE TO 1 bar; SETTLE TIME 1 min; TEST TIME 1 min; MEASURE PRESSURE DROP DURING TEST TIME, MAX ALLOWABLE 2 mbar.", "c": "Pressure-decay test of the coolant path with a stated maximum drop. Air class 2:4:1 = particles : water : oil (ISO 8573-1).", "m": null, "cost": null}, {"name": "Internal volume, 0.5 bar", "text": "ENSURE GORE POLYVENT EX+ STL ST IS NOT INSTALLED.\nINJECT ATMOSPHERIC AIR CONFORMING TO ISO 8573-1:2010 CLASS [2:4:1].\nY-SPLITTER RECOMMENDED FOR TWO ACCESS PORTS.\nTEST PARAMETERS: PRESSURISE TO 0.5 bar; SETTLE TIME 1 min; TEST TIME 1 min; MEASURE PRESSURE DROP DURING TEST TIME, MAX ALLOWABLE 2 mbar.\nFIT GORE POLYVENT EX+ STL ST.", "c": "Pressure-decay test of the sealed internal volume. Fit the vent after testing. Air class 2:4:1 = particles : water : oil (ISO 8573-1).", "m": null, "cost": null}]},
      {"id": "n11_2", "topic": "Rotor balance", "text": "MOUNT VIA FRONT CASING 4x MOUNTING POINTS (SEE SECTION B-B) TO RUN ON FRONT BEARING.\nFIT A TEMPORARY RUNNING BUSHING OVER THE ROTOR SHAFT AGAINST THE REAR OF [] WITH LOCKNUT TO MAINTAIN THE SHAFT SPACER STACK.\nTIGHTEN LOCKNUT TO [] Nm.\nDO NOT USE THREADLOCKER.\nBALANCE SPECIFICATION TO ISO 21940-11: ROTOR MUST BE DYNAMICALLY BALANCED TO BALANCING GRADE G2.5.\nMAXIMUM ALLOWABLE UNBALANCE [] g·mm ([] g AT R[]).\nREFERENCE SPEED [] rpm.\nAPPROX. ROTOR MASS [] kg.\nADD BALANCE WEIGHTS TO CORRECTION PLANES 1 AND 2 (SEE SECTION A-A).\nCORRECT UNBALANCE BY ADDING [] BALANCE WEIGHTS, EACH FASTENED WITH A MINIMUM OF TWO FIXINGS.\nFOR FINER ADJUSTMENT, FIXING WITHOUT BALANCE WEIGHT MAY BE USED.\nRECORD ADDED MASSES, FASTENERS AND POSITIONS IN THE BUILD MANUAL.", "c": "Dynamic balance to ISO 21940-11. Record added weights and positions in the build manual.", "m": [], "cost": 3, "types": []},
      {"id": "n11_3", "topic": "Rotor sleeve fit", "text": "PRIOR TO INSTALLATION OF ITEM 2, CLEAN DIRT AND DEBRIS FROM THE ROTOR SURFACE AND BETWEEN THE MAGNETS USING ACETONE AND LINT-FREE WIPES.\nPAY SPECIAL ATTENTION TO THE ROTOR SURFACE AREA LOCATED BETWEEN THE TWO SLEEVES.\nTHIS MAY REMOVE ANY PEN MARKS.\nITEM 1 MUST BE COOLED TO [] °C; MAXIMUM PRESS FORCE [] kN.\nPLACE ASSEMBLY IN A VACUUM OVEN AT [] °C FOR [] HOURS FOLLOWING INSTALLATION OF BOTH ROTOR SLEEVES, THEN REMOVE AND COOL TO AMBIENT TEMPERATURE.\nPRIOR TO INSTALLATION OF ITEM 3, CLEAN DIRT AND DEBRIS FROM THE ROTOR END FACES AND THE ROTOR SURFACE AREA LOCATED BETWEEN THE TWO SLEEVES.\nAPPLY ITEM 7 ADHESIVE TO THICKNESS [].\nOVEN CURE AT [] °C.", "c": "Cooled press fit with a force limit, then vacuum-oven stabilise and adhesive cure.", "m": [], "cost": 3, "types": []},
      {"id": "n11_4", "topic": "Thermal press fit", "text": "HEAT LAMINATIONS TO [] °C BEFORE ASSEMBLY.\nPRESS LIMIT [] kN.\nONCE LAMINATIONS HAVE BEEN REMOVED FROM THE OVEN, THE PRESS OPERATION MUST BE COMPLETED WITHIN [] s.\nIF THIS CANNOT BE ACHIEVED, ABORT THE OPERATION AND RE-HEAT THE LAMINATIONS AS ABOVE.", "c": "Heat the laminations before pressing. The press must finish within the time window.", "m": [], "cost": 3, "types": []}
    ]}
  ]
};
